import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.hw3Av5Vn.js";const s="/llamatron/assets/grooves.BOPbFu4y.svg",d="/llamatron/assets/groove_editor.DLvazIlM.svg",f=JSON.parse('{"title":"Grooves","description":"","frontmatter":{},"headers":[],"relativePath":"GROOVES.md","filePath":"GROOVES.md"}'),n={name:"GROOVES.md"};function c(h,e,i,g,l,v){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="grooves" tabindex="-1">Grooves <a class="header-anchor" href="#grooves" aria-label="Permalink to &quot;Grooves&quot;">​</a></h1><p>A groove moves notes off the grid, as swing does on a drum machine. This page covers the Grooves page and the groove editor.</p><p><img src="'+s+'" alt="The Grooves page"></p><h2 id="how-a-groove-works" tabindex="-1">How a Groove Works <a class="header-anchor" href="#how-a-groove-works" aria-label="Permalink to &quot;How a Groove Works&quot;">​</a></h2><p>A groove is a row of cells, one bar of sixteenths to start with, and each cell says how late (<code>+</code>) or early (<code>-</code>) a note that falls in it plays, as a percentage of the cell. <code>16</code> on every second sixteenth is the classic 58% swing, and <code>32</code> is the triplet feel of 66%.</p><p>Grooves follow time rather than steps. The row repeats its own length from the start of each scene, and a note takes the amount of the cell its time falls in, whatever the step size or play direction of its pattern. A moved note keeps its gate, so a delayed note also ends later, and a step&#39;s CC values move with its note. Grooves are applied in real time and in every kind of export alike, so nothing depends on Live&#39;s groove pool. A grab reads the other track&#39;s notes where the grid puts them, since a groove changes only timing.</p><h2 id="factory-grooves" tabindex="-1">Factory Grooves <a class="header-anchor" href="#factory-grooves" aria-label="Permalink to &quot;Factory Grooves&quot;">​</a></h2><p>Every set has the factory grooves: <code>none</code>, which plays straight and is what a new song uses; <code>swing 54</code>, <code>swing 58</code>, <code>swing 62</code> and <code>swing 66</code> on sixteenths; <code>8th swing 58</code> and <code>8th swing 66</code> on eighths; and <code>push</code>, which plays the off-beat sixteenths early. A factory groove can be opened and copied, but not changed, renamed or deleted, and a groove of your own can&#39;t take a factory groove&#39;s name.</p><h2 id="grooves-page" tabindex="-1">Grooves Page <a class="header-anchor" href="#grooves-page" aria-label="Permalink to &quot;Grooves Page&quot;">​</a></h2><p>Press <code>V</code> on the main screen to open the Grooves page. The list shows each groove&#39;s cells, the length of a cell, and how many songs, scenes and tracks use the groove.</p><table tabindex="0"><thead><tr><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td><code>A</code></td><td>Adds a straight groove of your own, named <code>groove 1</code> and so on, and opens it.</td></tr><tr><td><code>Enter</code></td><td>Opens the groove: one of yours to edit, or a factory groove to look at.</td></tr><tr><td><code>C</code></td><td>Copies the groove, factory or yours, to the end of your own grooves. Copying is how to get a factory groove you can change.</td></tr><tr><td><code>N</code></td><td>Renames one of your grooves, updating every song, scene and track that chose it.</td></tr><tr><td><code>M</code></td><td>Picks one of your grooves up: <code>↑↓</code> carry it, and <code>Enter</code> drops it.</td></tr><tr><td><code>S</code></td><td>Sorts your grooves by name.</td></tr><tr><td><code>Bksp</code></td><td>Deletes one of your grooves, once nothing uses it.</td></tr></tbody></table><h2 id="choosing-a-groove" tabindex="-1">Choosing a Groove <a class="header-anchor" href="#choosing-a-groove" aria-label="Permalink to &quot;Choosing a Groove&quot;">​</a></h2><p>The song chooses a groove on the Song page, and a scene or a track can choose another on its own page, or <code>off</code> to play straight. The track&#39;s choice wins over the scene&#39;s, and the scene&#39;s over the song&#39;s, except that <code>off</code> anywhere plays straight. A kick track set to <code>off</code> therefore stays straight in a swung scene, and a scene set to <code>off</code> stays straight even for a swung hi-hat track.</p><h2 id="groove-editor" tabindex="-1">Groove Editor <a class="header-anchor" href="#groove-editor" aria-label="Permalink to &quot;Groove Editor&quot;">​</a></h2><p><img src="'+d+'" alt="The groove editor"></p><p>The groove editor shows one groove&#39;s cells in a row, with the groove&#39;s name above them.</p><table tabindex="0"><thead><tr><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td>Left, Right</td><td>Move along the cells.</td></tr><tr><td>Digits</td><td>Type an amount; a minus sign is kept while typing into a negative cell.</td></tr><tr><td><code>[</code>, <code>]</code> or Up, Down</td><td>Change the amount by one.</td></tr><tr><td><code>I</code>, <code>D</code></td><td>Insert a straight cell before the cursor, or remove the cursor&#39;s cell.</td></tr><tr><td><code>S</code></td><td>Changes the length of a cell, going round a 32nd, sixteenth, eighth and quarter note.</td></tr><tr><td><code>N</code></td><td>Renames the groove, updating every song, scene and track that chose it.</td></tr></tbody></table><p>Amounts run from -50 to 50, so that notes can never change order, and a groove has 1 to 32 cells. A groove wider than the screen scrolls sideways as the cursor moves, and the line with the name says which cells are shown, such as <code>cells 1-11 ›</code>. A factory groove opens the same way, but only to look at.</p>',18)])])}const y=o(n,[["render",c]]);export{f as __pageData,y as default};
